from pathlib import Path
import re,json
ROOT=Path(__file__).resolve().parents[2]
LEAN=ROOT/'lean'
ENDPOINTS=[n for v in json.loads((ROOT/'validation/final_theorems.json').read_text())['endpoint_groups'].values() for n in v]
CAT=[]

def named_blocks(rel,prefix=None):
 s=(LEAN/rel).read_text()
 a=list(re.finditer(r'^theorem (\w+)\b',s,re.M)); out=[]
 for i,m in enumerate(a):
  stop=a[i+1].start() if i+1<len(a) else s.find('\nend',m.end())
  b=s[m.start():stop].strip()
  b=re.sub(r'\n/--.*?-/\s*$','',b,flags=re.S)
  if prefix is None or m[1].startswith(prefix): out.append(b)
 return out

def examples(rel,names,include=None):
 s=(LEAN/rel).read_text(); a=list(re.finditer(r'^example\b',s,re.M)); out=[]
 assert len(a)==len(names),(rel,len(a),len(names))
 for i,m in enumerate(a):
  stop=a[i+1].start() if i+1<len(a) else s.find('\nend',m.end())
  if include is not None and i not in include: continue
  b=s[m.start():stop].strip()
  out.append(b.replace('example','theorem '+names[i],1))
 return out

def interface(id,imports,opens,blocks,extras=''):
 text=''.join('import '+m+'\n' for m in imports)
 parent_open = ('Round3' if id in ['A397588','A389536','A389537','A389542'] else ('Round4' if id not in ['A378580','A378581'] else ''))
 base_open = 'PowerSeries' + ('' if id=='A380056' else ' Hanna.Series')
 text+='\n/-!\n# '+id+': separate formal proof entry\n\nAI-generated by ChatGPT (OpenAI) for Dev Goyal. Independent human review pending.\nThe explicit theorem types below fix the source and all advertised conclusions.\nThe complete constructive proofs and their shared dependencies are included in\nthe imported first-party modules; this entry contains checked proof terms.\n-/\n\nnamespace FinalCollection.'+id+'\n\n'+(('open '+parent_open+'\n') if parent_open else '')+'open '+base_open+' '+opens+'\n\nnoncomputable section\nattribute [local instance] Classical.propDecidable\n\n'
 text+='\n\n'.join(blocks)+'\n\n'+extras+'\nend\nend FinalCollection.'+id+'\n'
 (LEAN/'Entries'/f'{id}.lean').write_text(text)
 return ['FinalCollection.'+id+'.'+x for x in re.findall(r'^theorem (\w+)',text,re.M)]

def row(id,title,status,summary,quals,imports,opens,blocks,filterfn,extras=''):
 new=interface(id,imports,opens,blocks,extras)
 CAT.append(dict(oeis_id=id,title=title,status=status,source_url='https://oeis.org/'+id,manuscript_tex='manuscripts/'+id+'.tex',manuscript_pdf='manuscripts/'+id+'.pdf',lean_file='lean/Entries/'+id+'.lean',imported_modules=imports,original_endpoints=[n for n in ENDPOINTS if filterfn(n)],new_endpoints=new,summary=summary,qualifications=quals))

row('A397588','Binary parity for a differential power series','proved conjecture and additional source assertion','For all n>=0, [x^n]A is odd iff n is a power of two. Also A=x modulo 3, so 3 divides every coefficient above degree one.',['The source conjecture begins at n=1. Divisibility by three was already stated without a conjecture label. Analytic asymptotics are not proved.'],['Round3.ElementaryContracts'],'',named_blocks('Round3/ElementaryContracts.lean','differential_'),lambda n:n.startswith('Round3.DifferentialParity.') or n.startswith('Round3.ElementaryContracts.differential_'))
row('A389536','A sparse residue pattern for a Mahler substitution equation','proved conjecture','For n>1 the residue modulo 4 is 2 exactly at n=2^k+1, and 0 elsewhere; A=x+2xC modulo 4, C=x+C^2.',['The source quotient by x is expressed by the equivalent division-free equation. Analytic claims in the entry are outside scope.'],['Round3.ElementaryContracts'],'',named_blocks('Round3/ElementaryContracts.lean','mahler_'),lambda n:n.startswith('Round3.MahlerParity.') or n.startswith('Round3.ElementaryContracts.mahler_'))
lac_names=['auxiliary_exists_unique','auxiliary_equation','inverse_right','inverse_left','normalized','source_equation','source_exists_unique','source_unique','series_mod_two','integer_decomposition','half_equation_mod_two','half_binary_support','residue_mod_four']
row('A389537','Residues of the inverse of an alternating lacunary series','proved conjecture','For n>2 the residue modulo 4 is 2 exactly at n=3*2^k, and 0 elsewhere. The integer series is the unique normalized solution of A(A-x)=A^2.',['The separate empirical sign-run observation is not proved. Integer halving precedes reduction modulo four.'],['Round3.LacunaryInverse'],'Round3.LacunaryInverse',examples('Round3/LacunaryContracts.lean',lac_names),lambda n:n.startswith('Round3.LacunaryInverse.') or n.startswith('Round3.ModFour.'))
square_names=['auxiliary_exists_unique','normalized','auxiliary_definition','inverse_equation','inverse_right','inverse_left','source_equation','source_exists_unique','source_unique','auxiliary_parity','inverse_involution','inverse_mod_four','series_mod_four','residue_mod_four','exceptional_iff','four_dvd_iff']
row('A389542','A reversion that becomes an involution modulo four','proved conjecture','For n>1 the residue modulo 4 is 2 iff n=2^k+1, and 0 otherwise, for the unique normalized integer solution of A(A^2-x^2)=4A^3.',['Source uniqueness is proved over the integers, not over arbitrary rings with two-torsion. No analytic value or radius statement is claimed.'],['Round3.SquareReversion'],'Round3.SquareReversion',examples('Round3/SquareContracts.lean',square_names),lambda n:n.startswith('Round3.SquareReversion.') or n.startswith('Round3.ModFour.'))
theta_names=['theta_constant_term','theta_coefficient_formula','minus_constant','plus_constant','quotient_identity','minus_source','plus_source','minus_exists_unique','plus_exists_unique','minus_unique','plus_unique','minus_series_mod_four','plus_series_mod_four','minus_congruence','plus_congruence','minus_square_iff','plus_square_iff','minus_four_dvd_iff','plus_four_dvd_iff']
for id,inds,sign,eq in [('A378580',{0,1,2,4,5,7,9,11,13,15,17},'minus','A(x/A)=Theta'),('A378581',{0,1,3,6,8,10,12,14,16,18},'plus','A(xA)=Theta')]:
 row(id,'Square-index residues for theta '+('quotient' if sign=='minus' else 'product')+' substitution','proved conjecture','The unique constant-one integer solution of '+eq+' is Theta modulo 4. At n>0 its residue is 2 iff n is a square, and 0 otherwise.',['The multiplicative unit inverse and compositional inverse are distinct. Analytic convergence and real special values are not proved.'],['Round3.ThetaSubstitution'],'ThetaSubstitution',examples('Round3/ThetaContracts.lean',theta_names,inds),lambda n,id=id:n.startswith('ThetaSubstitution.a'+id[1:]+'_') or n.startswith('ThetaSubstitution.theta_') or n.startswith('Round3.ModFour.'))
row('A195194','Parity and convergence of an infinite nested reversion','proved conjecture with general construction','For every n>=0 the coefficient is odd iff n=2^k. Arbitrarily weighted infinite normalized tails exist uniquely over every commutative ring, and a depth-d nest agrees through degree d+1.',['Convergence means coefficient stabilization of formal series, with no analytic assertion. The source starts at n=1.'],['Round4.NestedContracts'],'Round4.NestedReversion',named_blocks('Round4/NestedContracts.lean'),lambda n:n.startswith('Round4.NestedReversion.') or n.startswith('Round4.NestedContracts.'),r'''theorem arbitrary_weights_unique {R : Type*} [CommRing R] (w : ℕ → R) :
    ∃! F : ℕ → PowerSeries R,
      (∀ j, Normalized (F j)) ∧ (∀ j,
        compose (pre (w j) (F (j+1))) (F j)=X ∧
        compose (F j) (pre (w j) (F (j+1)))=X) :=
  Round4.NestedReversion.source_existence_uniqueness w

theorem arbitrary_finite_depth {R : Type*} [CommRing R] (w : ℕ → R) (d j : ℕ) :
    (X : PowerSeries R)^(d+2) ∣ approximation w d j-tail w j :=
  Round4.NestedReversion.approximation_agrees w d j
''')
row('A393172','Powers of two in a Catalan substitution congruence','proved conjecture','For n>1 the residue modulo 4 is 2 iff n is a power of two, and 0 otherwise; the complete series is 2C-x modulo 4.',['Normalized source equation A(x-x^2)=x+A(x)^2 is constructed uniquely. The standard Catalan parity mechanism is not claimed as a new general result.'],['Round4.CatalanContracts'],'Round4.CatalanComposition',named_blocks('Round4/CatalanContracts.lean','first_'),lambda n:n.startswith('Round4.CatalanContracts.first_') or n.startswith('Round4.CatalanComposition.a393172_') or n.startswith('Round4.CatalanComposition.A_') or n.startswith('Round4.SquareComposition.'),r'''theorem complete_series_mod_four :
    PowerSeries.map (Int.castRingHom (ZMod 4)) (CatalanComposition.A : PowerSeries ℤ)=
      2*catalan-X := by
  rw [CatalanComposition.map_A, CatalanComposition.A_mod_four]

theorem divisibility_complement (n : ℕ) (hn : 1<n) :
    (4 : ℤ) ∣ coeff ℤ n (CatalanComposition.A : PowerSeries ℤ) ↔
      ¬∃ k : ℕ, n=2^k :=
  CatalanComposition.a393172_four_dvd_iff n hn
''')
row('A393171','A modulus-eight lift for a Catalan substitution sequence','proved conjecture','For n>2 the residue modulo 8 is 4 iff n=2^k or 2^k+1 with k>=1, and 0 otherwise. Source identities link B=x+B(C)^2 to A(x-x^2)=x+A^2.',['The exact integral decomposition A=2C-x+4K is proved before reducing modulo eight.'],['Round4.CatalanContracts'],'Round4.CatalanComposition',named_blocks('Round4/CatalanContracts.lean','second_'),lambda n:n.startswith('Round4.CatalanContracts.second_') or n.startswith('Round4.CatalanComposition.a393171_') or n.startswith('Round4.CatalanComposition.B_') or n=='Round4.CatalanComposition.A_integer_decomposition' or n.startswith('Round4.SquareComposition.'),r'''theorem link_to_first_sequence :
    (B : PowerSeries ℤ)=X+(CatalanComposition.A : PowerSeries ℤ)^2 := rfl

theorem link_composed_catalan :
    compose (B : PowerSeries ℤ) catalan=CatalanComposition.A :=
  CatalanComposition.B_composed_catalan

theorem complete_series_mod_eight :
    PowerSeries.map (Int.castRingHom (ZMod 8)) (B : PowerSeries ℤ)=
      X+X^2+4*(catalan-X-X*catalan) := by
  rw [CatalanComposition.map_B, CatalanComposition.B_mod_eight]

theorem divisibility_complement (n : ℕ) (hn : 2<n) :
    (8 : ℤ) ∣ coeff ℤ n (B : PowerSeries ℤ) ↔
      ¬∃ k : ℕ, 1≤k ∧ (n=2^k ∨ n=2^k+1) :=
  CatalanComposition.a393171_eight_dvd_iff n hn
''')
row('A392210','Odd-index evenness in a nested binomial equation','elementary observed pattern formalized','The unique normalized integer solution of D=x+D(x/(1-x))^2 has even coefficient at degree 2n-1 for every n>1.',['This is the source apparent pattern and a direct characteristic-two square consequence. No analytic interpretation of the nested title is claimed.'],['Round4.CatalanContracts'],'Round4.CatalanComposition',named_blocks('Round4/CatalanContracts.lean','third_'),lambda n:n.startswith('Round4.CatalanContracts.third_') or n.startswith('Round4.NestedBinomial.') or n.startswith('Round4.SquareComposition.'))
row('A380056','Congruences for exponential coefficients of (exp(x)-1)/cos(2x)','two proved conjectures and stronger classification','For n>=1, a(n)=1 modulo 4. For all n>=0, a(n)=2*2^n+3*4^n modulo 5, so 5 divides a(n) iff 4 divides n.',['These are exponential coefficients n![x^n]A, not ordinary rational coefficients. The literal rational EGF and its uniqueness are formally proved. Modular convolution does not divide by factorials in finite characteristic.'],['Round4.ExpCosineContracts'],'',named_blocks('Round4/ExpCosineContracts.lean'),lambda n:n.startswith('Round4.ExpCosine.') or n.startswith('Round4.ExpCosineContracts.'),r'''theorem mod_five_exponential_formula (n : ℕ) :
    (ExpCosine.a n : ZMod 5)=2*2^n+3*4^n :=
  ExpCosine.a380056_mod_five_formula n

theorem mod_five_period (n : ℕ) :
    (ExpCosine.a (n+4) : ZMod 5)=(ExpCosine.a n : ZMod 5) :=
  ExpCosine.a380056_mod_five_period n
''')
for id,sel in [('A380060',['implicit_','a380060_']),('A380680',['explicit_','a380680_'])]:
 blocks=[b for b in named_blocks('Round4/ThetaRationalContracts.lean') if any(re.match(r'theorem (\w+)',b)[1].startswith(p) for p in sel)]
 explicit=id=='A380680'; d=2 if explicit else 1
 row(id,('Twice-square support: a corrected rational theta conjecture' if explicit else 'Square support in an implicit rational theta equation'),('false conjecture refuted and corrected theorem proved' if explicit else 'proved conjecture'),('For n>0 the residue modulo 4 is 2 exactly at twice-square indices, and 0 otherwise. The original square-support claim is false: a(1)=4, a(2)=6.' if explicit else 'The unique implicit integer solution has residue 2 modulo 4 exactly at positive square indices and 0 elsewhere.'),['The formal source is the explicit positive-index formula (2) in OEIS. A separate formal Laurent-series equivalence to the bilateral title is not claimed. No convergence or real special-value assertion is proved.'],['Round4.ThetaRationalContracts'],'ThetaSubstitution Round4.ThetaRational',blocks,lambda n,id=id:n.startswith('Round4.ThetaRational.a'+id[1:]+'_') or n in ['Round4.ThetaRational.ratio_quotient','Round4.ThetaRational.sigma_coeff_finsum'] or (id=='A380060' and n in ['Round4.ThetaRational.existence_uniqueness','Round4.ThetaRational.map_solution','Round4.ThetaRational.solution_mod_four']) or n.startswith('Round4.ThetaRationalContracts.a'+id[1:]+'_') or n.startswith('Round4.ThetaRationalContracts.'+('explicit_' if id=='A380680' else 'implicit_')),f'''theorem complete_series_mod_four :
    PowerSeries.map (Int.castRingHom (ZMod 4)) {id}=1+2*squareSeries {d} :=
  Round4.ThetaRational.a{id[1:]}_series_mod_four
''')

for r in CAT:
 r['implementation_modules']={'A397588':['Round3.DifferentialParity'],'A389536':['Round3.MahlerParity'],'A389537':['Round3.LacunaryInverse'],'A389542':['Round3.SquareReversion'],'A378580':['Round3.ThetaSubstitution'],'A378581':['Round3.ThetaSubstitution'],'A195194':['Round4.NestedReversion'],'A393172':['Round4.CatalanComposition','Round4.SquareComposition'],'A393171':['Round4.CatalanComposition','Round4.SquareComposition'],'A392210':['Round4.NestedBinomial','Round4.SquareComposition'],'A380056':['Round4.ExpCosine'],'A380060':['Round4.ThetaRational'],'A380680':['Round4.ThetaRational']}[r['oeis_id']]

(ROOT/'catalogue/recent_entries.json').write_text(json.dumps(CAT,indent=2)+'\n')
